import React, { useEffect, useState } from 'react';
import Feedback from './Feedback';
import Donate from './Donate';
import Volunteer from './Volunteer';
import UserProfileCard from './UserProfileCard';

const styles = {
  panelContainer: {
    display: 'flex',
    gap: 24,
    padding: 24,
    alignItems: 'flex-start',
    backgroundColor: '#f5f7fa',
    borderRadius: 12,
  },
  leftPanel: {
    width: 320,
    flexShrink: 0,
  },
  middlePanel: {
    flex: 1,
  },
  card: {
    background: '#ffffff',
    padding: 20,
    borderRadius: 12,
    boxShadow: '0 4px 12px rgba(0,0,0,0.05)',
    border: '1px solid #e0e0e0',
    marginBottom: 20,
  },
  actionBox: {
    padding: 15,
    borderRadius: 8,
    border: '1px solid',
    marginBottom: 15,
  },
  feedbackBox: {
    backgroundColor: '#fffbe6',
    borderColor: '#ffe58f',
  },
  donateBox: {
    backgroundColor: '#f0fff4',
    borderColor: '#b7eb8f',
  },
  volunteerBox: {
    backgroundColor: '#e6f7ff',
    borderColor: '#91d5ff',
  }
};

export default function VolunteerDonorSection({ me = {}, events = [], token, setMsg, activities }) {
  const [profile, setProfile] = useState(null);
  const [userActivities, setUserActivities] = useState([]);

  useEffect(() => {
    if (!token) return;

    (async () => {
      try {
        const res = await fetch(
          (process.env.REACT_APP_API || "http://localhost:4000") + "/api/auth/me",
          { headers: { Authorization: `Bearer ${token}` } }
        );

        if (!res.ok) throw new Error("Failed to fetch profile");

        const data = await res.json();
        setProfile(data);
        setUserActivities(data.activities || []);

      } catch (err) {
        console.error(err);
        setMsg("Failed to load profile");
      }
    })();
  }, [token]);

  return (
    <div style={styles.panelContainer}>

      {/* LEFT PANEL: User Profile */}
      <div style={styles.leftPanel}>
        <UserProfileCard 
          token={token} 
          setMsg={setMsg} 
          me={profile} 
          activities={userActivities}
          showPoints={false}
          showBadges={false}
          customStats={[
            { label: 'Total Donations', value: activities?.donations?.length || 0 },
            { label: 'Events Participated', value: activities?.volunteers?.length || 0 }
          ]}
        />
      </div>

      {/* MIDDLE PANEL: Quick Actions */}
      <div style={styles.middlePanel}>
        <h3 style={{ marginBottom: 12 }}>⭐ Quick Actions</h3>

        <div style={styles.card}>
          <h4 style={{ marginTop: 0, borderBottom: '1px solid #eee', paddingBottom: 10 }}>Actions</h4>

          {/* Feedback Box */}
          <div style={{...styles.actionBox, ...styles.feedbackBox}}>
            <h5 style={{ marginTop: 0, marginBottom: 8 }}>Give Feedback 💬</h5>
            <Feedback token={token} setMsg={setMsg} />
          </div>

          {/* Donate Box */}
          <div style={{...styles.actionBox, ...styles.donateBox}}>
            <h5 style={{ marginTop: 0, marginBottom: 8 }}>Make a Donation 💸</h5>
            <Donate token={token} setMsg={setMsg} />
          </div>

          {/* Volunteer Box */}
          <div style={{...styles.actionBox, ...styles.volunteerBox}}>
            <h5 style={{ marginTop: 0, marginBottom: 8 }}>Volunteer for Event 🤝</h5>
            <Volunteer token={token} events={events} setMsg={setMsg} />
          </div>
        </div>

        {/* Activity Summary */}
        <div style={styles.card}>
          <h4 style={{ marginTop: 0, marginBottom: 12 }}>📊 Your Activity</h4>
          
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <div style={{ 
              padding: 12, 
              background: '#f0fff4', 
              borderRadius: 8, 
              border: '1px solid #b7eb8f',
              textAlign: 'center'
            }}>
              <div style={{ fontSize: 24, fontWeight: 'bold', color: '#28a745' }}>
                {activities?.volunteers?.length || 0}
              </div>
              <div style={{ fontSize: 12, color: '#666', marginTop: 4 }}>Events Participated</div>
            </div>
            
            <div style={{ 
              padding: 12, 
              background: '#fffbe6', 
              borderRadius: 8, 
              border: '1px solid #ffe58f',
              textAlign: 'center'
            }}>
              <div style={{ fontSize: 24, fontWeight: 'bold', color: '#d46b08' }}>
                {activities?.donations?.length || 0}
              </div>
              <div style={{ fontSize: 12, color: '#666', marginTop: 4 }}>Donations Made</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
